export function bootstrap(name: string): string {
  return `ready:${name}`;
}

export function route(enabled) {
  if (enabled) return "active";
  return "idle";
}

export function search(first: string, second: string): string {
  if (first.length > 0) return first && second ? first : second;
  return second;
}

